if mc.shareChosen~=true then
mc.shareStats=nil
end
if mc.autoTeamChosen~=true then
mc.autoTeam=nil
end
for nc,oc in pairs(N.DEFAULTS)do
if mc[nc]~=nil and type(mc[nc])==type(oc)then
O[nc]=mc[nc]
else
O[nc]=oc
end
end
O.seenVersion=type(mc.seenVersion)==Qfe[889]and mc.seenVersion or nil
if mc.griffinWatch==true and mc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,Qfe[1064]
end
if O.pickPortal==Qfe[909]then
O.portals,O.pickPortal=false,Qfe[904]
