if O.huntCards==Qfe[1993]then
O.huntCards=Qfe[1994]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
end
O.play=true
for pc,qc in ipairs({Qfe[1995],Qfe[1996],Qfe[1997],Qfe[1998],Qfe[1999],Qfe[2000],Qfe[2001],Qfe[2002]})do
O[qc]=true
end
end
end
