end
return{seen=true,nums={stat=mq,loSeen=nq,hiSeen=oq,transformTo=jq},why=string.format(Qfe[2398],mq,tostring(nq),tostring(oq))}
end
return{seen=true,buff=fq,nums={maxSeen=gq.max,steps= #gq.vals,transformTo=jq},why=string.format(Qfe[2399],fq,tostring(gq.max))}
end
if Oo.family==Qfe[2163]then
local tq,uq,vq={},{},nil
for wq,xq in ipairs(Mo.steps)do
for yq,zq in pairs(xq.reset or{})do
table.insert(tq,zq)
table.insert(uq,xq.drop)
