if#tq<3 then
return{why=Qfe[2400]}
end
return{seen=true,nums={atSeen=Uo(tq),hitSeen=Uo(uq),meter=vq},why=string.format(Qfe[2401],#tq)}
end
if Oo.family==Qfe[2132]then
return{why=Qfe[2402]}
end
return{why=Qfe[2403]}
end
function pb.learn(Aq)
local Bq={}
for Cq in pairs(Aq.ids or{})do
local Dq,Eq=pcall(pb.guess,Cq)
for Fq,Gq in ipairs(Dq and type(Eq)==Qfe[1982]and Eq or{})do
if Gq.playable and not Gq.hand then
local Hq,Iq=pcall(pb.evidence,Aq,Cq,Gq)
if Hq and type(Iq)==Qfe[1982]and Iq.seen then
local Jq=type(P.pasBook[Cq])==Qfe[1982]and P.pasBook[Cq]or{}
local Kq=type(Jq[Gq.pid])==Qfe[1982]and Jq[Gq.pid]or nil
local Lq={}
for Mq,Nq in pairs(Gq.nums or{})do
Lq[Mq]=Nq
end
for Oq,Pq in pairs(Iq.nums or{})do
Lq[Oq]=Pq
end
local Qq=Kq~=nil and Kq.family==Gq.family and(Kq.buff==nil or Iq.buff==nil or Kq.buff==Iq.buff)
Jq[Gq.pid]={family=Gq.family,name=Gq.name,nums=Lq,buff=Iq.buff or(Kq and Kq.buff),who=Iq.who or Gq.who,trigger=Gq.trigger,keyword=Gq.keyword,sure=(Qq and(tonumber(Kq.runs)or 0)>=1)and Qfe[2344]or Qfe[2404],runs=(Qq and(tonumber(Kq.runs)or 0)or 0)+1,at=os.time(),why=Iq.why}
P.pasBook[Cq]=Jq
table.insert(Bq,{id=Cq,g=Gq,e=Jq[Gq.pid]})
elseif Hq and type(Iq)==Qfe[1982]then
table.insert(Bq,{id=Cq,g=Gq,miss=Iq.why})
else
table.insert(Bq,{id=Cq,g=Gq,miss=Qfe[2405]..tostring(Iq)})
end
end
end
end
pb._model={}
return Bq
end
function pb.unexplained(Rq,Sq)
