local Wq={}
for Xq,Yq in pairs(Rq.own)do
if(Yq.by[Sq]or 0)>0 and not Tq[Xq]then
table.insert(Wq,{w=Qfe[2406],b=Xq,n=Yq.by[Sq],max=Yq.max})
end
end
for Zq,_q in pairs(Rq.foeBuffs)do
if _q.near>0 and _q.first>=Rq.firstPlaced[Sq]-1 and not Tq[Zq]then
table.insert(Wq,{w=Qfe[2407],b=Zq,n=_q.foes,max=_q.max})
end
