function ib.now()
if ib._at and U.now()-ib._at<10 then
return ib._t,ib._base
end
local Meb=(P.train.on and P.train.on.base)or ib.team()
local Neb=table.clone(Meb)
table.sort(Neb)
ib._t,ib._base,ib._at=ib.target(),table.concat(Neb,Qfe[2839]),U.now()
return ib._t,ib._base
end
function ib.valueFor(Oeb)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local Peb=P.trainSim[Oeb.key]
if not(Peb and Peb.ok and os.time()-(Peb.at or 0)<6*3600)then
return 0,1
end
local Qeb,Reb=ib.now()
local Seb={}
for Teb,Ueb in ipairs(P.savedTeam or{})do
Seb[Teb]=Ueb
end
table.sort(Seb)
if not(Qeb and Peb.uuid==Qeb.uuid and(Peb.base==Reb or Peb.base==table.concat(Seb,Qfe[2839])))or not ib.eligible(Oeb)then
return 0,1
end
local Veb=ib.perRun(Oeb.key,Qeb.id)or 0
local Web=math.max(1,Qeb.need-Qeb.have)
return O.goalValue*math.min(Veb,Web)/Web,Peb.slow or 1
end
function ib.scan()
local Xeb=O.trainTakedowns and O.sim and ib.now()
if not Xeb then
return
end
local Yeb=(P.train.on and P.train.on.base)or ib.team()
for Zeb,_eb in ipairs(Yeb)do
if _eb==Xeb.uuid then
return
end
end
local afb,bfb=0,0
for cfb,dfb in ipairs(W.lastScored or{})do
if afb>=3 or bfb>=2 then
break
end
if ib.eligible(dfb)then
local efb=P.trainSim[dfb.key]
local ffb=efb and efb.uuid==Xeb.uuid and os.time()-(efb.at or 0)<6*3600
local gfb=ib.plan(dfb,Xeb,Yeb)
if not ffb then
bfb=bfb+1
end
if gfb.ok then
afb=afb+1
end
end
end
local hfb=ib.bestInfinite()
if hfb then
ib.plan(hfb,Xeb,Yeb)
end
end
function ib.bestInfinite()
local ifb,jfb
for kfb,lfb in ipairs(W.lastScored or{})do
if lfb.kind==Qfe[2001]and ib.eligible(lfb)then
local mfb,nfb=P.train.real[lfb.key],lfb.rec or W.rec(lfb.key)
local ofb=(tonumber(nfb.timed)or 0)>0 and nfb.sec/nfb.timed/60 or 0
local pfb=(mfb and mfb.n>0 and ofb>0)and(mfb.sum/mfb.n)/ofb or 0
if pfb<=0 then
pfb=db.hiveTrainRate(lfb.key)or 0
end
if pfb>(jfb or 0)then
ifb,jfb=lfb,pfb
end
end
end
return ifb
end
function ib.ratio()
local qfb=P.train.cal
if not(qfb and(qfb.n or 0)>0 and(qfb.sim or 0)>0)then
return 1
end
return U.clamp(qfb.real/qfb.sim,0.05,2)
end
function ib.perRun(rfb,sfb)
local tfb=P.train.real[rfb]
if tfb and tfb.n>0 then
return tfb.sum/tfb.n,true
end
local ufb=db.hiveTrain(rfb,sfb)
if ufb then
return ufb,true
end
local vfb,wfb=0,0
local xfb=W.isInf(rfb)
for yfb,zfb in pairs(P.train.real)do
if W.isInf(yfb)==xfb then
vfb,wfb=vfb+zfb.sum,wfb+zfb.n
end
end
if wfb>0 then
return vfb/wfb,true
end
local Afb=P.trainSim[rfb]
return Afb and Afb.tk and Afb.tk*ib.ratio()or nil,false
end
function ib.eligible(Bfb)
if Bfb.kind==Qfe[2434]or Bfb.kind==Qfe[1996]then
return false,Qfe[3146]
end
if Bfb.kind==Qfe[2002]then
return false,Qfe[3147]
end
if P.labForce and P.labForce==Bfb.key then
return false,Qfe[3148]
end
if N.Levels[Bfb.level]and N.Levels[Bfb.level]._randomequippedmode then
return false,Qfe[3149]
end
if(P.train.bad[Bfb.key]or 0)>os.time()then
return false,Qfe[3150]..os.date(Qfe[3040],P.train.bad[Bfb.key])
end
local Cfb=Bfb.rec or W.rec(Bfb.key)
if Cfb.runs>=3 and Cfb.wins/Cfb.runs<0.8 then
return false,Qfe[3151]
end
local Dfb=P.simRes[Bfb.key]
if Dfb and Dfb.trust and not Dfb.trust.ok then
return false,Qfe[3152]
end
return true
end
function ib.plan(Efb,Ffb,Gfb)
local Hfb=N.session()
local Ifb=table.clone(Gfb)
table.sort(Ifb)
local Jfb=table.concat(Ifb,Qfe[2839])
local Kfb=(tonumber((P.simCal[Efb.key]or{}).n)or 0)>0
local Lfb=Kfb and 1.3 or 2
local Mfb=Jfb..Qfe[2296]..Ffb.uuid..(Kfb and Qfe[3153]or Qfe[3154])..Qfe[3155]
local Nfb=P.trainSim[Efb.key]
if Nfb and Nfb.sig==Mfb and not Nfb.pending and os.time()-(Nfb.at or 0)<6*3600 then
return Nfb
end
local Ofb={sig=Mfb,base=Jfb,uuid=Ffb.uuid,at=os.time(),ok=false,margin=Lfb,pending=true}
P.trainSim[Efb.key]=Ofb
local Pfb,Qfb=gb.levelFor(Efb)
if Efb.ldOverride then
Pfb=Efb.ldOverride
end
if not Pfb then
Ofb.why,Ofb.pending=Qfe[3156],nil
return Ofb
end
local Rfb=gb.info(Pfb,Efb.key,Qfb,Efb.mod)
local Sfb={}
for Tfb,Ufb in ipairs(Gfb)do
local Vfb=Hfb.collection:get_unit_by_uuid(Ufb)
if Vfb then
table.insert(Sfb,Vfb)
end
end
local Wfb=Hfb.collection:get_unit_by_uuid(Ffb.uuid)
if not Wfb or#Sfb==0 then
Ofb.why,Ofb.pending=Qfe[3157],nil
return Ofb
end
local Xfb=gb.run(Rfb,gb.teamFrom(Sfb,Rfb.map),{hpMul=1})
local Yfb=Rfb.infinite and gb.unbound(Pfb)
local Zfb=Yfb and W.infTier(gb.run(Rfb,gb.teamFrom(Sfb,Rfb.map),{hpMul=Lfb}).wave)or nil
local _fb={}
for agb,bgb in ipairs(Sfb)do
if not V.isFarm(bgb.unit_id)then
local cgb,dgb=pcall(V.score,bgb,Efb.mod)
table.insert(_fb,{i=agb,sc=cgb and dgb or 0})
end
end
table.sort(_fb,function(egb,fgb)
return egb.sc<fgb.sc
end)
local ggb
for hgb=1,math.min(3,#_fb)do
local igb=table.clone(Sfb)
igb[_fb[hgb].i]=Wfb
local jgb=gb.teamFrom(igb,Rfb.map)
local kgb=gb.run(Rfb,jgb,{hpMul=Lfb,train=Ffb.uuid})
if(Yfb and W.infTier(kgb.wave)>=Zfb)or(not Yfb and kgb.won)then
local lgb=gb.run(Rfb,jgb,{hpMul=1,train=Ffb.uuid})
local mgb=(lgb.tk or 0)/math.max(0.5,lgb.t/60)
if(lgb.won or Yfb)and(not ggb or mgb>math.max(ggb.rate*1.5,ggb.rate+1))then
ggb={out=Sfb[_fb[hgb].i].unit_id,r=lgb,rate=mgb,trial=igb}
end
end
end
Ofb.ownMin=Xfb.t/60
if not ggb then
Ofb.why=Yfb and string.format(Qfe[3158],Zfb,Kfb and Qfe[3159]or Qfe[3160])or Kfb and Qfe[3161]or Qfe[3162]
else
Ofb.out,Ofb.tk,Ofb.minutes=ggb.out,ggb.r.tk or 0,ggb.r.t/60
Ofb.uuids={}
for ngb,ogb in ipairs(ggb.trial)do
table.insert(Ofb.uuids,ogb.uuid)
end
Ofb.slow=(Xfb.won and not Yfb)and Ofb.minutes/math.max(0.1,Ofb.ownMin)or 1
if Ofb.tk<=0 and next(P.train.real)==nil then
Ofb.why=Qfe[3163]
elseif Ofb.slow>ib.SLOW then
Ofb.why=string.format(Qfe[3164],math.floor((Ofb.slow-1)*100+0.5))
else
Ofb.ok=true
end
end
Ofb.pending=nil
F.log(1,Qfe[3165],string.format(Qfe[3166],Efb.label,V.name(Ffb.id),Ofb.out and(Qfe[3167]..V.name(Ofb.out))or Qfe[903],Ofb.ok and string.format(Qfe[3168],math.floor((ib.perRun(Efb.key,Ffb.id)or 0)+0.5),Ffb.what,Ofb.minutes,Ofb.ownMin)or tostring(Ofb.why)))
F.saveSoon()
return Ofb
end
function ib.home()
local pgb=P.train.on
if not pgb then
return
end
P.train.on=nil
F.saveSoon()
if not ib.same(ib.team(),pgb.uuids or{})then
F.log(1,Qfe[3165],Qfe[3169])
if not O.autoTeam then
P.savedTeam=nil
end
return
end
if P.savedTeam and ib.same(P.savedTeam,pgb.base)then
ab.restoreTeam()
else
ab.equipTeam(pgb.base,Qfe[3170])
end
F.log(1,Qfe[3165],V.name(pgb.out or Qfe[2217])..Qfe[3171])
end
function ib.apply(qgb)
local rgb=P.testTeam
if rgb and(rgb.left or 0)>0 and qgb and rgb.key==qgb.key then
ib.home()
return F.status(Qfe[3172],Qfe[3173])
end
local sgb=O.trainTakedowns and ib.target()or nil
if not sgb then
ib.home()
return F.status(Qfe[3172],O.trainTakedowns and Qfe[3174]or Qfe[3175])
end
local tgb=V.name(sgb.id)
local ugb=string.format(Qfe[3176],sgb.what,U.fmt(sgb.have),U.fmt(sgb.need))
local vgb=P.train.on
local wgb=vgb and vgb.base or ib.team()
for xgb,ygb in ipairs(wgb)do
if ygb==sgb.uuid then
return F.status(Qfe[3172],string.format(Qfe[3177],tgb,ugb))
end
end
local zgb,Agb=ib.eligible(qgb)
local Bgb
if zgb then
F.status(Qfe[3172],string.format(Qfe[3178],tgb,qgb.label))
Bgb=ib.plan(qgb,sgb,wgb)
zgb,Agb=Bgb.ok,Bgb.why
end
if not zgb then
ib.home()
return F.status(Qfe[3172],string.format(Qfe[3179],tgb,ugb,qgb.label,tostring(Agb)))
end
if not(vgb and ib.same(ib.team(),Bgb.uuids))then
ab.equipTeam(Bgb.uuids,string.format(Qfe[3180],tgb,V.name(Bgb.out),qgb.label))
local Cgb=U.now()
while U.now()-Cgb<4 and not ib.same(ib.team(),Bgb.uuids)do
task.wait(0.25)
end
if not ib.same(ib.team(),Bgb.uuids)then
if P.savedTeam and ib.same(P.savedTeam,wgb)then
ab.restoreTeam()
else
ab.equipTeam(wgb,Qfe[3181])
end
P.train.bad[qgb.key]=os.time()+3600
F.log(1,Qfe[3165],Qfe[3182]..qgb.label..Qfe[3183])
return F.status(Qfe[3172],tgb..Qfe[3184])
end
P.train.on={uuid=sgb.uuid,id=sgb.id,to=sgb.to,what=sgb.what,have=sgb.have,need=sgb.need,got=0,base=wgb,uuids=Bgb.uuids,out=Bgb.out,key=qgb.key,at=os.time()}
F.log(1,Qfe[3165],string.format(Qfe[3185],tgb,V.name(Bgb.out),qgb.label,ugb))
end
P.train.on.key=qgb.key
local Dgb,Egb=ib.perRun(qgb.key,sgb.id)
F.status(Qfe[3172],string.format(Qfe[3186],tgb,V.name(Bgb.out),qgb.label,ugb,math.floor((Dgb or 0)+0.5),Egb and Qfe[903]or Qfe[3187]))
end
function ib.text()
if not O.trainTakedowns then
return Qfe[3188]
end
local Fgb=ib.target()
if not Fgb then
return Qfe[3189]
end
local Ggb,Hgb=0,0
for Igb,Jgb in pairs(P.train.real)do
Ggb=Ggb+Jgb.sum
Hgb=Hgb+Jgb.n
end
local Kgb=Hgb>0 and Ggb/Hgb or nil
local Lgb={}
for Mgb,Ngb in ipairs(P.train.log)do
