table.insert(Lgb,string.format(Qfe[3190],Ngb.got,nb.keyName and nb.keyName(Ngb.key)or Ngb.key,Ngb.won and Qfe[2725]or Qfe[2726]))
end
end
return string.format(Qfe[3191]..Qfe[3192]..Qfe[3193]..Qfe[3194]..Qfe[3195],V.name(Fgb.id),U.fmt(Fgb.need),Fgb.what,V.name(Fgb.to),U.fmt(Fgb.have),Kgb and string.format(Qfe[3196],math.floor(Kgb+0.5),math.ceil((Fgb.need-Fgb.have)/math.max(1,Kgb)))or Qfe[903],#Lgb>0 and(Qfe[3197]..table.concat(Lgb,Qfe[2357])..Qfe[2564])or Qfe[903])
end
function ab.every(Ogb,Pgb)
local Qgb=U.now()
if ab.last[Ogb]and Qgb-ab.last[Ogb]<Pgb then
return false
end
ab.last[Ogb]=Qgb
