end
function ab.refreshLive()
local Rgb=P.live
local Sgb=type(Rgb.tn)==Qfe[1982]and os.time()-(tonumber(Rgb.tn.at)or 0)<3600
if ab.every(Qfe[2622],Sgb and 600 or(type(Rgb.tn)==Qfe[1982]and 30 or 60))then
local Tgb,Ugb=pcall(ab.tnRefresh)
if not Tgb then
F.log(1,Qfe[2368],Qfe[3198]..tostring(Ugb))
end
end
local Vgb,Wgb=F.request(Qfe[3199],Qfe[3200])
if Vgb and type(Wgb)==Qfe[1982]and Wgb.current_uuid then
local Xgb=(Rgb.normal and Rgb.normal.uuid==Wgb.current_uuid)and Rgb.normal.lost or 0
local Ygb=(Rgb.normal and Rgb.normal.uuid==Wgb.current_uuid)and Rgb.normal.doneUuid or nil
local Zgb=N.GS.CHALLENGE_DURATION or 1800
local _gb=(math.floor(os.time()/Zgb)+1)*Zgb
Rgb.normal={uuid=Wgb.current_uuid,level=Wgb.current_level_id,challenge=Wgb.current_challenge,value=W.rewardValue(Wgb.current_reward),expires=_gb,lost=Xgb,doneUuid=Ygb}
end
local ahb,bhb=F.request(Qfe[3201],Qfe[3202])
if ahb and type(bhb)==Qfe[1982]and bhb.current_uuid then
local chb=type(bhb.current_level)==Qfe[1982]and bhb.current_level or{}
local dhb=W.dailyMod(chb._challenge_uuid or bhb.current_uuid,chb._daily_challenge_weak_against or bhb.weak_against,chb._daily_challenge_strong_against or bhb.strong_against)
local ehb=(Rgb.daily and Rgb.daily.uuid==bhb.current_uuid)and Rgb.daily.lost or 0
local fhb=(Rgb.daily and Rgb.daily.uuid==bhb.current_uuid)and Rgb.daily.doneUuid or nil
local ghb=type(bhb.current_level)==Qfe[1982]and gb.slim(bhb.current_level)or nil
if ghb then
ghb._challenge=bhb.current_challenge
end
Rgb.daily={uuid=bhb.current_uuid,value=W.rewardValue(bhb.current_reward),challenge=bhb.current_challenge,mod=dhb,lost=ehb,doneUuid=fhb,ld=ghb}
end
local hhb,ihb=F.request(Qfe[2493],Qfe[2494])
if hhb and type(ihb)==Qfe[1982]then
Rgb.event=nil
for jhb,khb in pairs(ihb)do
local lhb=type(khb)==Qfe[1982]and khb.current_level_data
if type(lhb)==Qfe[889]then
lhb=N.Levels[lhb]
end
if lhb then
local mhb=gb.slim(lhb)
mhb._difficulty=mhb._difficulty or Qfe[2426]
Rgb.event={level=lhb.id or jhb,name=lhb.name,pad=N.GS.ACTIVE_EVENT_CHALLENGES and N.GS.ACTIVE_EVENT_CHALLENGES[jhb],board=jhb,map=lhb.map,weather=khb.current_weather,ld=mhb,forecast=type(khb.forecast)==Qfe[1982]and{map=khb.forecast.map,weather=khb.forecast.weather,map_hint=khb.forecast.map_hint,weather_hint=khb.forecast.weather_hint}or nil}
end
end
end
local nhb,ohb,phb=F.request(Qfe[3203],Qfe[3204])
if nhb and type(ohb)==Qfe[1982]and type(ohb.world_ids)==Qfe[1982]then
local qhb={}
for rhb,shb in ipairs(ohb.world_ids)do
local thb=N.Worlds[shb]
local uhb=thb and type(thb.levels)==Qfe[1982]and(thb.levels[Qfe[2423]]or thb.levels[1])
if uhb and N.Levels[uhb.id]then
table.insert(qhb,{level=uhb.id,world=shb})
end
end
Rgb.artifact={list=qhb,interval=ohb.interval,ends=tonumber(ohb.ends_at),ad=type(phb)==Qfe[1982]and phb or(Rgb.artifact and Rgb.artifact.interval==ohb.interval and Rgb.artifact.ad)or nil}
end
Rgb.at=os.time()
F.saveSoon()
end
function ab.npcQuestPays(vhb)
local whb=N.data(Qfe[3205])or{}
local xhb=whb[vhb]
local yhb=type(xhb)==Qfe[1982]and xhb.quest_reward
if type(yhb)~=Qfe[1982]then
return false
end
if(tonumber(yhb.gem_reward)or 0)>0 then
return true
end
for zhb,Ahb in ipairs(U.list(yhb.item))do
if type(Ahb)==Qfe[1982]and Ahb.item_id then
return true
end
end
return type(yhb.resource_reward)==Qfe[1982]and next(yhb.resource_reward)~=nil
end
function ab.npcQuests()
if not O.rewards or F.where~=Qfe[2053]then
return
end
local Bhb=N.session()
local Chb=N.data(Qfe[3206])
local Dhb=workspace:FindFirstChild(Qfe[3207])
local Ehb=M.Character and M.Character:FindFirstChild(Qfe[3208])
if not(Bhb and N.QCC and type(Chb)==Qfe[1982]and Dhb and Ehb)then
return
end
P.npcTried=type(P.npcTried)==Qfe[1982]and P.npcTried or{}
for Fhb,Ghb in pairs(Chb)do
local Hhb=type(Fhb)==Qfe[889]and Fhb:match(Qfe[3209])
local Ihb
for Jhb,Khb in ipairs(Hhb and type(Ghb)==Qfe[1982]and type(Ghb.dialogue)==Qfe[1982]and Ghb.dialogue or{})do
for Lhb,Mhb in ipairs(type(Khb)==Qfe[1982]and type(Khb.options)==Qfe[1982]and Khb.options or{})do
if type(Mhb)==Qfe[1982]and type(Mhb.accept_npc_quest)==Qfe[1982]then
Ihb=Mhb.accept_npc_quest.quest_id
end
end
end
local Nhb=Ihb and Dhb:FindFirstChild(Hhb)
if Nhb and ab.npcQuestPays(Ihb)and os.time()-(tonumber(P.npcTried[Ihb])or 0)>3600 then
local Ohb=Bhb.quest_handler:get_first_unique_quest_by_id(Ihb)
local Phb,Qhb=false,false
if Ohb then
Phb,Qhb=pcall(N.QCC.is_quest_complete,Bhb,Ohb)
end
if not Ohb or(Phb and Qhb)then
local Rhb=tostring(((N.data(Qfe[3205])or{})[Ihb]or{}).quest_name or Ihb)
local Shb=Ehb.CFrame
local Thb=Nhb:GetPivot()
Ehb.CFrame=CFrame.new(Thb.Position+Thb.LookVector*5+Vector3 .new(0,3,0),Thb.Position)
task.wait(1.2)
if not Ohb then
local Uhb,Vhb=F.request(Qfe[3210],Qfe[3211],Ihb)
local Whb=U.now()
while U.now()-Whb<5 and not Ohb do
task.wait(0.3)
Ohb=Bhb.quest_handler:get_first_unique_quest_by_id(Ihb)
end
if Ohb then
F.log(1,Qfe[2628],Qfe[3212]..Rhb)
Phb,Qhb=pcall(N.QCC.is_quest_complete,Bhb,Ohb)
else
P.npcTried[Ihb]=os.time()
F.log(2,Qfe[2628],string.format(Qfe[3213],Rhb,tostring(Uhb and Vhb)))
end
end
if Ohb and Phb and Qhb then
local Xhb,Yhb=tonumber(N.cur(Qfe[2046]))or 0,hb.have(Qfe[2472])
local Zhb,aib=F.request(Qfe[3214],Qfe[3215],Ohb.uuid)
task.wait(2)
local bib,cib=(tonumber(N.cur(Qfe[2046]))or 0)-Xhb,hb.have(Qfe[2472])-Yhb
if Zhb and aib then
F.log(1,Qfe[2628],string.format(Qfe[3216],Rhb,bib,cib))
pcall(F.feed,Qfe[2630],Qfe[3217]..Rhb,string.format(Qfe[3218],bib,cib),{earned={gems=bib}})
else
P.npcTried[Ihb]=os.time()
F.log(1,Qfe[2628],string.format(Qfe[3219],Rhb,tostring(Zhb and aib)))
end
end
Ehb.CFrame=Shb
task.wait(0.5)
end
end
end
end
function ab.rewards()
if not O.rewards then
return F.status(Qfe[3220],Qfe[909])
end
local dib=N.session()
local eib=N.prof()
if not(dib and eib)then
