local mob=tostring(lob and lob.name or bob)
local nob={key=Qfe[2670]..dob.id..Qfe[2775],kind=Qfe[2021],first=true,level=dob.id,diff=Qfe[908],label=W.levelName(dob.id)..Qfe[2776]}
