if wob then
local yob=(N.prof()or{}).level_data or{}
local zob={}
for Aob,Bob in ipairs(U.list(lob.levels))do
if Bob.id~=dob.id and not qob[Bob.id]and W.done(yob,Bob.id,Qfe[908])then
table.insert(zob,W.levelName(Bob.id))
end
end
F.log(1,Qfe[2603],string.format(Qfe[3346],mob,#zob>0 and(Qfe[3347]..table.concat(zob,Qfe[2094]))or Qfe[3348],xob and(Qfe[3349]..tostring(xob))or Qfe[903]))
W.lastScored=nil
else
F.log(1,Qfe[2603],string.format(Qfe[3350],mob,tostring(xob or(uob and vob)or Qfe[2516])))
