for cub,dub in pairs(Vtb.profile_data.collection.owned_units)do
local eub=dub.unit_id
if not Xtb[cub]and not Xtb[eub]and N.Units[eub]and not V.isFarm(eub)and not V.allyBuff(eub)and os.time()-(tonumber(Utb.tried[eub])or 0)>ab.LAB.AGAIN then
