end
local iub,jub
for kub,lub in ipairs(Wtb)do
if not V.isFarm(lub.id)and not V.allyBuff(lub.id)and lub.uuid~=O.evolveUnit then
local mub=kb.score(lub.u)
if not iub or mub<jub then
iub,jub=lub,mub
end
end
end
if not iub then
return
end
Utb.tried[_tb.id]=os.time()
local nub=0
for oub in pairs(Utb.tried)do
nub=nub+1
