function eb.upgradeGain(kyb,lyb,myb,nyb,oyb,pyb)
local qyb,ryb=lyb[myb],lyb[myb+1]
local syb=(qyb.cd>0 and qyb.damage/qyb.cd or 0)
local tyb=(ryb.cd>0 and ryb.damage/ryb.cd or 0)*V.aoe(ryb.atk,ryb.range)/math.max(0.3,V.aoe(qyb.atk,qyb.range))
local uyb=syb>0 and kyb*(tyb/syb-1)or(pyb or 0)
local vyb=lyb[myb+2]
if vyb and myb+1<lyb.max and vyb.cd>0 and ryb.cd>0 and syb>0 then
local wyb=kyb*((vyb.damage/vyb.cd)/syb-1)
local xyb=nyb+vyb.cost*oyb
if wyb/xyb>uyb/nyb then
uyb=uyb+(wyb/xyb*nyb-uyb)*0.5
end
end
local yyb=(ryb.range or 0)>(qyb.range or 0)and(1+((ryb.range-qyb.range)/math.max(1,qyb.range)))or 1
return math.max(0,uyb)*yyb
end
function eb.dpsFor(zyb,Ayb)
if Ayb<=0 then
return 0
end
local Byb={}
for Cyb,Dyb in ipairs(zyb)do
if not Dyb.farm and Dyb.gain>0 then
table.insert(Byb,Dyb)
end
end
table.sort(Byb,function(Eyb,Fyb)
return Eyb.gain/Eyb.cost>Fyb.gain/Fyb.cost
end)
local Gyb,Hyb=0,0
for Iyb,Jyb in ipairs(Byb)do
if Ayb<=0 then
break
end
Hyb=Jyb.gain/Jyb.cost
local Kyb=math.min(1,Ayb/Jyb.cost)
Gyb=Gyb+Jyb.gain*Kyb
Ayb=Ayb-Jyb.cost*Kyb
end
return Gyb+math.max(0,Ayb)*Hyb*0.7
end
function eb.shieldDps(Lyb,Myb,Nyb,Oyb,Pyb,Qyb,Ryb)
if(Oyb or 0)<=0 or(Lyb or 0)<=0 or(Pyb or 0)<=0 then
return Lyb or 0
end
Myb,Nyb,Qyb=math.max(0.3,Myb or 2),math.max(1,Nyb or 1),Qyb or 1
local Syb=Lyb*Qyb*Myb/Nyb
return Pyb*Nyb/((Oyb/math.max(1,Ryb or 1)+math.max(1,Pyb/Syb))*Myb)/Qyb
end
function eb.shieldGain(Tyb,Uyb,Vyb,Wyb,Xyb,Yyb,Zyb,_yb)
local azb,bzb=V.attackInfo(Uyb.atk,Uyb.range),V.attackInfo(Wyb.atk,Wyb.range)
local czb=eb.shieldDps(Tyb,(tonumber(Uyb.cd)or 2)*(Zyb or 1),azb.n,Xyb,Yyb,_yb,azb.hits)
local dzb=eb.shieldDps(Vyb,(tonumber(Wyb.cd)or 2)*(Zyb or 1),bzb.n,Xyb,Yyb,_yb,bzb.hits)
local ezb=math.max(0,((tonumber(Wyb.range)or 0)-(tonumber(Uyb.range)or 0))/math.max(1,tonumber(Uyb.range)or 1))
return math.max(0,dzb-czb)+czb*ezb
end
function eb.shieldWork(fzb,gzb,hzb,izb,jzb,kzb,lzb,mzb,nzb)
if(izb or 0)<=0 then
return 0
end
local ozb=3*izb*(jzb or 1)/math.max(1,kzb or 20)
if(hzb or 0)>=ozb then
return 0
end
return math.max(1,fzb or 1)*math.max(1,nzb or 1)/math.max(0.3,gzb or 2)*math.min(lzb or 0,mzb or 0)
end
function eb.holdGain(pzb,qzb,rzb,szb)
if not pzb or(qzb or 0)<=0 then
return 0
end
local tzb,uzb=tonumber(pzb.stun)or 0,tonumber(pzb.slowTime)or 0
if tzb<=0 and uzb<=0 then
return 0
end
local vzb,wzb=tzb>0 and tzb or uzb,tzb>0 and 1 or(tonumber(pzb.slowPct)or 0.3)
local xzb=wzb*vzb/(vzb+(tonumber(pzb.ccCd)or 8))
local yzb=xzb/math.max(0.1,1-xzb)
return qzb*yzb*U.clamp(rzb or 0.5,0,1)*math.min(1,(tonumber(pzb.n)or 1)/2)/(1+(szb or 0))
end
function eb.bleedGain(zzb,Azb,Bzb,Czb)
if(zzb or 0)<=0 then
return 0
end
local Dzb=Azb or 0
for Ezb,Fzb in ipairs(Bzb or{})do
Dzb=math.max(Dzb,(tonumber(Fzb.hp)or 0)*0.5)
end
return zzb*Dzb*(Czb and 0.5 or 1)
end
function eb.bleedShare(Gzb,Hzb,Izb,Jzb)
if Gzb<=0 or not Hzb then
return 0
end
if Jzb then
return Hzb==0 and Gzb or Gzb/(Hzb+1)
end
return Izb<Hzb and Gzb/(Hzb-Izb)or 0
end
function eb.keepsUp(Kzb,Lzb,Mzb,Nzb,Ozb)
local Pzb=Kzb.coming
if not(Pzb and#Pzb>0 and Kzb.waveSec)then
return true
end
local Qzb=Kzb.eff or 1
local Rzb=Kzb.money-Mzb
local Szb=(Kzb.teamDps or 0)*(Kzb.shieldK or 1)+(Nzb or 0)*Qzb+eb.dpsFor(Lzb,math.max(0,Rzb))*Qzb
local Tzb=(Kzb.farmNow or 0)+(Ozb or 0)
local Uzb=(Kzb.roadSec or 130)*U.clamp(Kzb.cover or 0.6,0.1,1)
local Vzb=Kzb.hpAlive or 0
for Wzb,Xzb in ipairs(Pzb)do
Vzb=math.max(0,Vzb+Xzb.hp-Szb*Kzb.waveSec)
local Yzb=Szb*Uzb
if Vzb>Yzb then
return false,Wzb,Yzb/math.max(1,Vzb)
end
if Wzb< #Pzb then
Szb=Szb+eb.dpsFor(Lzb,(Xzb.reward or 0)+Tzb)*Qzb*(0.85^Wzb)
end
end
return true
end
function eb.decide(Zzb,_zb)
local aAb=U.clamp(_zb.cover or 0.6,0.1,1)
local bAb=math.max(O.clearSec,0.7*(_zb.roadSec or 50)*aAb)
local cAb=(_zb.clearSec or 0)>bAb
_zb.piling=_zb.piling and cAb
local dAb=_zb.attackers>0 and _zb.pressure<math.min(O.safeReach,aAb*0.75)and not _zb.piling and not cAb
local eAb=_zb.pressure>=math.min(O.dangerReach,aAb*0.9)or(_zb.piling and _zb.enemies>=18)
local fAb,gAb
for hAb,iAb in ipairs(Zzb)do
if iAb.farm then
if O.farmUnits and iAb.gain>0 then
iAb.payback=iAb.cost/iAb.gain
if _zb.left-1>=iAb.payback+(_zb.farmSpare or O.farmSpare)and(not fAb or iAb.payback<fAb.payback)then
fAb=iAb
end
end
else
iAb.ratio=iAb.gain/math.max(1,iAb.cost)
if not gAb or iAb.ratio>gAb.ratio then
gAb=iAb
end
end
end
if _zb.leak and _zb.attackers>0 then
local jAb
for kAb,lAb in ipairs(Zzb)do
local mAb=not _zb.airLeak or(lAb.e and bb.cardAir(lAb.e.id))
if lAb.place and not lAb.farm and mAb and lAb.cost<=_zb.money and not(lAb.e and V.allyBuff(lAb.e.id))and(not jAb or lAb.gain>jAb.gain)then
jAb=lAb
end
end
if jAb then
return jAb,string.format(Qfe[3586],math.floor(_zb.leak*100))
end
end
local nAb=_zb.future<_zb.wantLeft*1.1
local oAb,pAb,qAb=true,nil,nil
if fAb then
oAb,pAb,qAb=eb.keepsUp(_zb,Zzb,fAb.cost,0,fAb.gain)
end
local rAb=_zb.coming and not eb.keepsUp(_zb,Zzb,0,0,0)
local sAb=false
if bb.random and fAb and not eAb and _zb.attackers>=2 and fAb.payback<=_zb.left/3 then
local tAb=0
for uAb,vAb in ipairs(bb.mine or{})do
if V.isFarm(vAb._stats.id.Value)then
tAb=tAb+1
end
end
sAb=not fAb.place or tAb<4
end
if rAb and _zb.attackers>0 then
eAb=true
end
local wAb=math.max(1,_zb.incomeRate or 20)
local xAb=_zb.waveSec or 20
local function yAb(zAb,AAb,BAb)
local CAb=math.max(0,(zAb.cost-_zb.money)/wAb)
local DAb=zAb.gain*math.max(0,BAb-CAb)
if AAb then
local EAb=math.max(0,_zb.money-zAb.cost)
local FAb=CAb+math.max(0,(AAb.cost-EAb)/wAb)
DAb=DAb+AAb.gain*math.max(0,BAb-FAb)
end
return DAb
end
local GAb,HAb
if _zb.attackers==0 and gAb then
local IAb=4*xAb
local JAb={}
for KAb,LAb in ipairs(Zzb)do
if LAb.place and not LAb.farm then
table.insert(JAb,{o=LAb,v=yAb(LAb,nil,IAb)})
end
end
table.sort(JAb,function(MAb,NAb)
return MAb.v>NAb.v
end)
local OAb=_zb.opener and JAb[_zb.opener]and _zb.opener or 1
local PAb=JAb[OAb]and JAb[OAb].o
GAb,HAb=PAb or gAb,OAb>1 and Qfe[3587]or Qfe[3588]
elseif fAb and dAb and nAb and not eAb and oAb then
GAb=fAb
HAb=string.format(Qfe[3589],fAb.payback,_zb.left,_zb.coming and#_zb.coming or 0)
elseif sAb then
GAb=fAb
HAb=string.format(Qfe[3590],fAb.payback,_zb.left)
elseif gAb then
GAb=gAb
if rAb then
HAb=string.format(Qfe[3591])
elseif eAb then
HAb=string.format(Qfe[3592],math.floor(_zb.pressure*100),math.floor(aAb*100))
elseif fAb and not oAb then
HAb=string.format(Qfe[3593],pAb or 1,math.floor((qAb or 0)*100))
elseif fAb and cAb then
HAb=string.format(Qfe[3594],math.min(999,math.floor(_zb.clearSec)),math.floor(bAb))
elseif fAb and _zb.piling then
HAb=string.format(Qfe[3595],_zb.enemies)
elseif fAb and not dAb then
HAb=Qfe[3596]
elseif fAb and not nAb then
HAb=Qfe[3597]
else
HAb=Qfe[3598]
end
end
if not GAb then
return nil
end
if GAb.cost>_zb.money then
local QAb
if not GAb.farm then
local RAb=((_zb.pressure or 0)>=0.95 and 0.5 or eAb and 2 or 6)*xAb
local SAb
for TAb,UAb in ipairs(Zzb)do
if not UAb.farm and UAb~=GAb and UAb.cost<=_zb.money then
local VAb=yAb(UAb,GAb,RAb)
local WAb=yAb(GAb,UAb,RAb)
if VAb>WAb and(not SAb or VAb>SAb)then
QAb,SAb=UAb,VAb
end
