gb.SHARE_FLOOR,gb.SHARE_STEP=0.03,0.5
function gb.shareLearn()
if bb.withOthers or bb.joinedMid or bb.random or bb.trialId or bb.stopping or#game:GetService(Qfe[882]):GetPlayers()>1 then
return
end
local tQb=bb.info
if type(tQb)~=Qfe[1982]or type(bb.predUnits)~=Qfe[1982]or#bb.predUnits==0 or not bb.key then
return
end
