local wQb={}
for xQb,yQb in pairs(bb.predOpt or{hpMul=1})do
wQb[xQb]=yQb
end
wQb.dealt={}
if not pcall(gb.runRaw,tQb,vQb,wQb)then
return
end
local zQb,AQb={},0
for BQb,CQb in ipairs(vQb)do
if not CQb.farm and not zQb[CQb.id]then
local DQb=(tonumber(wQb.dealt[V.name(CQb.id)])or 0)+(tonumber(wQb.dealt[Qfe[2548]..CQb.id])or 0)
zQb[CQb.id]={e=CQb,d=DQb}
AQb=AQb+DQb
end
end
if AQb<=0 then
return
end
local EQb=gb.cal(bb.key)
