local GQb=FQb and Qfe[3660]or Qfe[3659]
local HQb={}
for IQb,JQb in pairs(type(EQb[GQb])==Qfe[1982]and EQb[GQb]or{})do
HQb[IQb]=JQb
end
local KQb,LQb=0,0
for MQb,NQb in pairs(zQb)do
NQb.p,NQb.r=NQb.d/AQb,tonumber(uQb[MQb])or 0
if NQb.p>=gb.SHARE_FLOOR or NQb.r>=gb.SHARE_FLOOR then
