NQb.step=U.clamp(gb.SHARE_STEP*math.max(0.5,1/(PQb+1))*math.log((NQb.r+gb.SHARE_FLOOR)/(NQb.p+gb.SHARE_FLOOR)),-math.log(2),math.log(2))
NQb.old,NQb.sn=OQb,PQb
KQb,LQb=KQb+NQb.step,LQb+1
end
end
if LQb<2 then
return
end
local QQb=KQb/LQb
local RQb={}
bb.shareRows={}
