bb.shareRows[SQb]={r=TQb.r,p=TQb.p}
end
end
for UQb,VQb in pairs(zQb)do
if VQb.step then
local WQb=(VQb.old and gb.ukNow(VQb.old,UQb))or gb.unitK(tQb,VQb.e,FQb)
