if math.abs(XQb/WQb-1)>=0.05 then
table.insert(RQb,{p=VQb.p,t=string.format(Qfe[3671],V.name(UQb),math.floor(VQb.r*100+0.5),math.floor(VQb.p*100+0.5),XQb,WQb)})
end
end
