function bb.buildPath()
bb.samples={}
local ulc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not ulc then
return
end
for vlc,wlc in pairs(ulc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[vlc.Name])then
local xlc={}
for ylc,zlc in ipairs(wlc.points or{})do
table.insert(xlc,zlc.part.Position)
end
local Alc=0
for Blc=2,#xlc do
Alc=Alc+(xlc[Blc]-xlc[Blc-1]).Magnitude
end
local Clc=0
for Dlc=2,#xlc do
local Elc,Flc=xlc[Dlc-1],xlc[Dlc]
local Glc=(Flc-Elc).Magnitude
local Hlc=math.max(1,math.floor(Glc/2))
for Ilc=0,Hlc-1 do
local Jlc=Elc:Lerp(Flc,Ilc/Hlc)
table.insert(bb.samples,{pos=Jlc,prog=(Clc+Glc*Ilc/Hlc)/math.max(1,Alc),lane=vlc.Name})
end
Clc=Clc+Glc
end
if xlc[#xlc]then
table.insert(bb.samples,{pos=xlc[#xlc],prog=1,lane=vlc.Name})
end
end
end
pcall(bb.readHidden,ulc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Klc=tonumber(bb.ld and bb.ld._portal_lanes)
local Llc=gb.laneList(bb.samples)
if Klc and Klc>=1 and Llc and#Llc>Klc then
bb.laneWant=Klc
end
bb.laneTotal=Llc and#Llc or 1
bb.countLanes()
