function bb.readHidden(Mlc)
local Nlc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Nlc)~=Qfe[1982]or not next(Nlc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Olc
for Plc,Qlc in pairs(Mlc)do
if Nlc[Plc.Name]and type(Qlc.points)==Qfe[1982]and#Qlc.points>=2 then
local Rlc={}
for Slc,Tlc in ipairs(Qlc.points)do
Rlc[Slc]=U.flat(Tlc.part.Position)
end
local Ulc={}
for Vlc,Wlc in ipairs(bb.samples)do
local Xlc=tostring(Wlc.lane)
Ulc[Xlc]=Ulc[Xlc]or{}
table.insert(Ulc[Xlc],Wlc)
end
local Ylc,Zlc
for _lc,amc in pairs(Ulc)do
local bmc=0
for cmc=1,#Rlc,math.max(1,math.floor(#Rlc/20))do
local dmc=math.huge
for emc,fmc in ipairs(amc)do
local gmc=(U.flat(fmc.pos)-Rlc[cmc]).Magnitude
if gmc<dmc then
dmc=gmc
end
end
bmc=bmc+dmc
end
if not Zlc or bmc<Zlc then
Ylc,Zlc=_lc,bmc
end
end
local hmc,imc,jmc,kmc,lmc,mmc={},nil,nil,nil,0,0
for nmc,omc in ipairs(Rlc)do
local pmc,qmc=nil,math.huge
for rmc,smc in ipairs(Ulc[Ylc])do
local tmc=(U.flat(smc.pos)-omc).Magnitude
if tmc<qmc then
qmc,pmc=tmc,smc.prog
end
end
mmc=math.max(mmc,qmc)
if jmc then
local umc=pmc-jmc
local vmc=(umc>0.002 and 1)or(umc< -0.002 and-1)or kmc
if kmc and vmc and vmc~=kmc then
table.insert(hmc,math.floor(jmc*1000+0.5)/1000)
end
kmc,lmc=vmc or kmc,lmc+math.abs(umc)
else
imc=pmc
end
jmc=pmc
if nmc%50==0 then
task.wait()
end
end
if jmc and mmc<=8 then
table.insert(hmc,math.floor(jmc*1000+0.5)/1000)
Olc=Olc or{}
Olc[Plc.Name]={from=math.floor((imc or 0)*1000+0.5)/1000,len=math.floor(lmc*1000+0.5)/1000,turns=hmc,road=Ylc}
end
end
end
if not Olc then
return
end
local wmc=bb.ld.map
P.maps[wmc]=P.maps[wmc]or{}
local xmc=P.maps[wmc].hidden
P.maps[wmc].hidden=Olc
if type(xmc)~=Qfe[1982]then
for ymc,zmc in pairs(Olc)do
F.log(1,Qfe[2650],string.format(Qfe[4008],ymc,zmc.len,tostring(zmc.road),math.floor((#zmc.turns-1)/2)))
end
F.saveSoon()
end
end
