if Mqc.hp>0 and Mqc.prog>Nqc+0.02 and Mqc.prog>(Iqc or 0)then
Iqc,Kqc=Mqc.prog,bb.laneW and Mqc.lane or nil
end
if Mqc.hp>0 and Mqc.fly and Mqc.prog>nqc+0.02 then
Jqc=true
end
end
end
local Oqc= #iqc>0 and(bb.pressure or 0)>=mqc-0.08
return{covEnd=mqc,airEnd=nqc,leak=Iqc,leakLane=Kqc,covL=tqc,airLeak=Jqc,push=Oqc,units= #iqc}
