bb.probe.Size=Vector3 .new(gHc*2,2.5,gHc*2)
bb.probe.CFrame=CFrame.new(fHc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return fHc
end
