end
table.insert(RIc.wave,tonumber(UIc)or 0)
if tonumber(VIc)then
RIc.kills=type(RIc.kills)==Qfe[1982]and RIc.kills or{}
table.insert(RIc.kills,math.floor(tonumber(VIc)))
while#RIc.kills>bb.LAYOUT_KEEP do
table.remove(RIc.kills,1)
end
end
while#RIc.sec>bb.LAYOUT_KEEP do
table.remove(RIc.sec,1)
end
while#RIc.wave>bb.LAYOUT_KEEP do
table.remove(RIc.wave,1)
end
end
