bb.CONTROL_WORDS={Qfe[4196],Qfe[4197],Qfe[4198],Qfe[4199]}
function bb.controlSpot(wJc,xJc)
if not bb.killZone()then
return nil
end
local yJc=gb.holds
if not yJc(wJc.id)or V.toggleOf(wJc.id)then
return nil
end
local zJc,AJc,BJc,CJc=1,0,0,{}
local DJc=bb.hurtSamples()
for EJc,FJc in ipairs(bb.mine or{})do
local GJc=FJc._stats
local HJc=GJc.id.Value
if GJc:FindFirstChild(Qfe[2234])and not V.isFarm(HJc)and not V.allyBuff(HJc)then
local IJc,JJc=U.flat(FJc:GetPivot().Position),GJc.range.Value
if yJc(HJc)and not V.toggleOf(HJc)then
BJc=BJc+1
table.insert(CJc,{p=IJc,r=JJc})
else
for KJc,LJc in ipairs(DJc)do
if(U.flat(LJc.pos)-IJc).Magnitude<=JJc then
zJc,AJc=math.min(zJc,LJc.prog),math.max(AJc,LJc.prog)
end
end
end
end
end
if AJc<=zJc then
zJc,AJc=0.75,0.98
end
local MJc=(xJc or BJc)+1
local NJc=({zJc,AJc,(zJc+AJc)/2,zJc-(AJc-zJc)/2})[MJc]
if not NJc then
return nil
end
local OJc=V.range(wJc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local PJc={}
for QJc,RJc in ipairs(bb.cands)do
local SJc,TJc,UJc=U.flat(RJc),0,0
for VJc,WJc in ipairs(DJc)do
if(U.flat(WJc.pos)-SJc).Magnitude<=OJc then
UJc=UJc+1
if math.abs(WJc.prog-NJc)<=0.05 then
TJc=TJc+1
local XJc=U.flat(WJc.pos)
for YJc,ZJc in ipairs(CJc)do
if(XJc-ZJc.p).Magnitude<=ZJc.r then
TJc=TJc-0.5
break
end
end
end
end
end
if TJc>0 then
table.insert(PJc,{pos=RJc,sc=TJc,cov=UJc})
end
if QJc%60==0 then
task.wait()
end
end
table.sort(PJc,function(_Jc,aKc)
return _Jc.sc>aKc.sc
end)
for bKc,cKc in ipairs(PJc)do
local dKc=bb.valid(cKc.pos,wJc.data)
if dKc then
F.log(1,Qfe[4048],string.format(Qfe[4200],V.name(wJc.id),bb.CONTROL_WORDS[MJc],math.floor(NJc*100+0.5)))
return dKc,cKc.cov,NJc
end
if bKc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(eKc)
local fKc,gKc=gb.holds(eKc.id)
if not fKc then
return nil
end
if V.killFed(eKc.id)then
return nil
end
local hKc,iKc={},0
for jKc,kKc in ipairs(bb.mine or{})do
local lKc=kKc._stats
local mKc=lKc.id.Value
if lKc:FindFirstChild(Qfe[2234])and not V.isFarm(mKc)and not V.allyBuff(mKc)and mKc~=eKc.id then
local nKc,oKc=pcall(bb.liveDps,kKc,mKc)
oKc=nKc and tonumber(oKc)or 0
if oKc>0 then
table.insert(hKc,{p=U.flat(kKc:GetPivot().Position),r=lKc.range.Value,d=oKc})
iKc=iKc+oKc
end
end
end
if#hKc==0 or iKc<=0 then
return nil
end
local pKc=bb.hurtSamples()
local qKc={}
for rKc,sKc in ipairs(pKc)do
local tKc,uKc=U.flat(sKc.pos),0
for vKc,wKc in ipairs(hKc)do
if(tKc-wKc.p).Magnitude<=wKc.r then
uKc=uKc+wKc.d
end
end
qKc[rKc]=uKc/iKc
end
local xKc=V.range(eKc.u,math.min(tonumber(gKc)or 0,3,V.rows(eKc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local yKc,zKc,AKc
for BKc,CKc in ipairs(bb.cands)do
local DKc,EKc,FKc=U.flat(CKc),0,0
for GKc,HKc in ipairs(pKc)do
if(U.flat(HKc.pos)-DKc).Magnitude<=xKc then
EKc=EKc+qKc[GKc]
FKc=FKc+1
end
end
if EKc>0 and(not zKc or EKc>zKc)then
local IKc=bb.valid(CKc,eKc.data)
if IKc then
yKc,zKc,AKc=IKc,EKc,FKc
end
end
if BKc%40==0 then
task.wait()
end
end
if not yKc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[eKc.id]then
bb.holdSaid[eKc.id]=true
F.log(1,Qfe[4048],string.format(Qfe[4201],V.name(eKc.id)))
end
return yKc,AKc or 0
end
function bb.bestSpot(JKc,KKc,LKc)
