local MKc=setmetatable({data=bb.hillData(JKc.data),_hillTry=true},{__index=JKc})
local NKc,OKc,PKc=pcall(bb.bestSpot,MKc,KKc,LKc)
if NKc and OKc then
return OKc,PKc
