end
end
table.insert(bb.trialTrace,string.format(Qfe[4215],hOc,gOc-(bb.startT or gOc),iOc,table.concat(kOc,Qfe[2839]),mOc,lOc+sOc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[hOc-1]or 0,bb.teamDps or 0))
end
