local AOc=math.min(30,gOc-(bb.startT or gOc))
bb.incomeRate=AOc>=8 and xOc/AOc or nil
for BOc,COc in ipairs(bb.enemies)do
local DOc=COc.m
local EOc=bb.track[DOc]
if not EOc then
